        }
        db.run(`INSERT INTO ${table} (version, name, applied_at) VALUES (?, ?, ?)`, [migration.version, migration.name, new Date().toISOString()])
      })
      applyMigration()
    } catch (e) {
      throw migrationFailedError(migration.version, e)
    }
    appliedNow.push(migration.version)
  }
  return appliedNow
}

